/* ----------------------------------------------------------------
     [ Start Products ]
-----------------------------------------------------------------*/

.products .item {
  margin-bottom: 15px;
  overflow: hidden;
  position: relative;
  text-align: center;
}

.products .item:hover .info {
  bottom: 30%;
}

.products .item:hover .info .icon {
  display: inline-block;
  margin-top: 38px;
}

.products .item:hover .product-img:after {
  height: 100%;
  opacity: .6;
  top: 0;
  visibility: visible;
}

.products .item .product-img {
  overflow: hidden;
  position: relative;
}

.products .item .product-img:after {
  background-color: rgba(0, 0, 0, 0.9);
  border-top: 2px solid #ce9e51;
  content: '';
  height: 25%;
  left: 0;
  opacity: 1;
  position: absolute;
  top: 75%;
  transition: all .4s;
  visibility: visible;
  width: 100%;
}

.products .item .info {
  color: #fff;
  bottom: 5%;
  left: 0;
  padding: 0 15px;
  position: absolute;
  transition: all .4s;
  width: 100%;
  z-index: 4;
}

.products .item .info h6,
.products .item .info h6 a {
  font-size: 16px;
  letter-spacing: 1px;
  margin-bottom: 5px;
  color: #fff;
}

.products .item .info span {
  font-size: 13px;
  font-style: italic;
  margin-bottom: 10px;
  color: #eee;
}

.products .item .info .icon {
  color: #eee;
  cursor: pointer;
  display: none;
  font-size: 16px;
  margin: 7px 10px;
  position: relative;
  width: 35px;
  height: 35px;
  line-height: 35px;
  border-radius: 50%;
  border: 1px solid #eee;
}

.products .item .info .icon .icon-text {
  visibility: hidden;
  opacity: 0;
  position: absolute;
  top: 0;
  left: 50%;
  font-size: 12px;
  text-transform: capitalize;
  margin-top: -6px;
  display: table;
  clear: both;
  transform: translate3d(-50%, -100%, 0);
  color: #fff !important;
  padding: 3px 8px;
  line-height: 1.5;
  border-radius: 3px;
  width: -moz-max-content;
  width: max-content;
  width: 80px;
  border-color: #ce9e51;
  background-color: #ce9e51;
}

.products .item .info .icon .icon-text:before {
  content: "";
  position: absolute;
  width: 0;
  height: 0;
  border-style: solid;
  bottom: -5px;
  left: 50%;
  right: auto;
  margin-bottom: 0;
  margin-left: -4px;
  margin-right: 0;
  border-width: 5px 5px 0 5px;
  border-color: transparent;
  border-top-color: #ce9e51;
}

.products .item .info .icon:hover {
  color: #ce9e51;
  border-color: #ce9e51;
}

.products .item .info .icon:hover .icon-text {
  visibility: inherit;
  opacity: 1;
}

