.side-panel {
  position: fixed;
  z-index: 10000;
  top: 0;
  bottom: 0;
  right: 0;
  width: 100%;
  max-width: 360px;
  height: 100vh;
  overflow: hidden;
  overflow-y: auto;
  background: #fff;
  transform: translateX(calc(100% + 80px));
  transition: transform .45s ease-in-out;
}

.side-panel.open {
  transform: translateX(0);
}

.side-panel .close-black-block-offcanvas {
  position: absolute;
  color: #fff;
  font-size: 15px;
  display: block;
  font-weight: normal;
  line-height: 1;
  border-radius: 50% 50% 50% 50%;
  padding: 4px 7px 5px 7px;
  border: 1px solid #ccc;
  z-index: 10;
  background-color: #fff;
  top: 15px;
  right: 15px;
}

