/*----to top style----*/

.to-top.fixed {
  opacity: 1;
  bottom: 30px;
}

.to-top {
  background: #ce9e51;
  bottom: 1150px;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.15);
  color: #fff;
  display: block;
  font-size: 15px;
  height: 50px;
  line-height: 48px;
  opacity: 0;
  position: fixed;
  right: 30px;
  text-align: center;
  transition: 1s ease-in-out;
  width: 50px;
  z-index: 333;
  -webkit-transition: 1s ease-in-out;
  border-radius: 100px;
  overflow: hidden;
  animation: pulse 2s infinite;
}

.to-top:focus {
  color: #fff;
}

.to-top:hover {
  color: #fff;
}

.to-top::before {
  -webkit-transform: scale(0);
  background: #ce9e51 none repeat scroll 0 0;
  border-radius: 200px;
  content: "";
  display: block;
  height: 200px;
  left: -50%;
  margin-top: -100px;
  position: absolute;
  top: 50%;
  transition-duration: 0.8s;
  transition: all 0.4s ease-out 0s;
  width: 200px;
  z-index: -1;
  -ms-transform: scale(0);
  -webkit-transition-duration: 0.8s;
  -webkit-transition: all 0.4s ease-out 0s;
  opacity: 0.3;
  transform: scale(0);
}

.to-top::after {
  -webkit-transform: scale(0);
  background: #ce9e51 none repeat scroll 0 0;
  border-radius: 200px;
  content: "";
  display: block;
  height: 200px;
  left: -50%;
  margin-top: -100px;
  position: absolute;
  top: 50%;
  transition: all 0.4s ease-in 0s;
  width: 200px;
  z-index: -1;
  -ms-transform: scale(0);
  -webkit-transition: all 0.4s ease-in 0s;
  opacity: 0.3;
  transform: scale(0);
  transition-delay: 0.3s;
}

.to-top:hover::after,
.to-top:hover::before {
  -webkit-transform: scale(4);
  -ms-transform: scale(4);
  opacity: 1;
  transform: scale(4);
}

