.wpcf7-submit {
  color: #ce9e51;
  width: auto;
  border: 1px solid #ce9e51;
  display: inline-block;
  font-size: 16px;
  padding: 7px 15px;
  position: relative;
  overflow: hidden;
  z-index: 1;
  transition-duration: 1.0s;
}

.wpcf7-submit:hover {
  color: #ffffff;
  border: 1px solid #ce9e51;
  background: #ce9e51;
}

.wpcf7-submit:hover::after {
  opacity: 1;
  transform: scale(4);
  -ms-transform: scale(4);
  -webkit-transform: scale(4);
}

.wpcf7-submit::before {
  background: #eee none repeat scroll 0 0;
  border-radius: 200px;
  content: "";
  display: block;
  height: 200px;
  left: -50%;
  margin-top: -100px;
  position: absolute;
  top: 50%;
  width: 200px;
  opacity: 0.3;
  z-index: -1;
  transform: scale(0);
  -ms-transform: scale(0);
  -webkit-transform: scale(0);
  transition: all 0.4s ease-out 0s;
  transition-duration: 0.8s;
}

.wpcf7-submit::after {
  background: #fff none repeat scroll 0 0;
  border-radius: 200px;
  content: "";
  opacity: 0.3;
  display: block;
  height: 200px;
  left: -50%;
  margin-top: -100px;
  position: absolute;
  top: 50%;
  width: 200px;
  z-index: -1;
  transform: scale(0);
  -ms-transform: scale(0);
  -webkit-transform: scale(0);
  transition: all 0.4s ease-in 0s;
  transition-delay: 0.3s;
}

