}

.img-box-slider .box-img:after {
  content: '\e870';
  font-family: 'Linearicons-Free';
  font-size: 45px;
  display: block;
  position: absolute;
  top: calc(50% + 15px);
  left: calc(50% - 25px);
  color: #fff;
  transition: 0.4s all ease-in-out;
  font-weight: 200;
  opacity: 0;
  transform: rotate(45deg);
}

.img-box-slider .fa-angle-left.slick-arrow {
  bottom: 0;
  position: absolute;
  left: 0;
  width: 50px;
  height: 50px;
  line-height: 50px;
  color: #ce9e51;
  text-align: center;
  cursor: pointer;
  z-index: 1;
  font-size: 30px;
  transition: ease .5s;
  -webkit-transition: ease .5s;
  -moz-transition: ease .5s;
  -o-transition: ease .5s;
  -ms-transition: ease .5s;
  bottom: 50%;
  left: -60px;
}

.img-box-slider .fa-angle-left.slick-arrow:hover {
  color: #ffffff;
}

.img-box-slider .fa-angle-right.slick-arrow {
  bottom: 0;
  position: absolute;
  left: 0;
  width: 50px;
  height: 50px;
  line-height: 50px;
  color: #ce9e51;
  text-align: center;
  cursor: pointer;
  z-index: 1;
  font-size: 30px;
  transition: ease .5s;
  -webkit-transition: ease .5s;
  -moz-transition: ease .5s;
  -o-transition: ease .5s;
  -ms-transition: ease .5s;
  bottom: 50%;
  left: initial;
  right: -60px;
}

.img-box-slider .fa-angle-right.slick-arrow:hover {
  color: #ffffff;
}

.img-box-slider .slick-dotted.slick-slider {
  margin-bottom: 30px;
}

.img-box-slider .slick-dots {
  position: absolute;
  bottom: -60px;
  display: block;
  width: 100%;
  padding: 0;
  margin: 0;
  list-style: none;
  text-align: center;
}

.img-box-slider .slick-dots li {
  position: relative;
  display: inline-block;
  width: 20px;
  height: 20px;
  margin: 0 5px;
  padding: 0;
  cursor: pointer;
}

.img-box-slider .slick-dots li button {
  font-size: 0;
  line-height: 0;
  display: block;
  width: 20px;
  height: 20px;
  padding: 5px;
  cursor: pointer;
  color: transparent;
  border: 0;
  outline: none;
  background: transparent;
}

.img-box-slider .slick-dots li button:hover {
  outline: none;
}

.img-box-slider .slick-dots li button:hover:before {
  opacity: 1;
}

.img-box-slider .slick-dots li button:focus {
  outline: none;
}

.img-box-slider .slick-dots li button:focus:before {
  opacity: 1;
}

.img-box-slider .slick-dots li button:before {
  font-family: "slick";
  font-size: 20px;
  line-height: 10px;
  position: absolute;
  top: 0;
  left: 5px;
  width: 20px;
  height: 5px;
  content: '';
  text-align: center;
  opacity: .25;
  background: #ce9e51;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.img-box-slider .slick-dots li.slick-active button:before {
